107	/**
108	 * Whether the commit this branch now points at is the one a pull request landed.
109	 *
110	 * Asks by head branch instead of scanning the repository's pull requests: that
111	 * list is paginated newest-first, so a branch whose pull request has since
112	 * fallen off the first page would read as unmerged. The number of branches one
113	 * issue owns is small, and this is only reached for those.
114	 *
115	 * ## Why the tip is part of the question
116	 *
117	 * "A pull request from this branch merged" and "this branch's work is in the base"
118	 * are different facts, and the name makes them look like one. A branch name is
119	 * reused: a parent issue's branch exists for as long as its children keep merging
120	 * into it, and a merge to the base can land part of it while the branch goes on
121	 * receiving work. Asking the first question answered *merged* for a tip carrying
122	 * undelivered work, so the parent's aggregation run found nothing to resume and
123	 * started on the base branch — where `create_pr` then had a head equal to its base
124	 * and could not open the pull request that delivers the branch (#441, #476).
125	 *
126	 * So the branch is merged when the commit it points at NOW is the commit a pull
127	 * request landed. A merged pull request from this branch whose `head.sha` is some
128	 * earlier commit says only that the branch has moved on since.
129	 *
130	 * A failed read stays "unmerged": resuming a branch that turned out to have
131	 * nothing new costs a run that starts one branch too early, and reporting a branch
132	 * with undelivered work as landed loses it.
133	 */
134	function headBranchMerged(repo: string, owner: string, branch: string, tip: string): boolean {
135	  const prs = gh("api", `repos/${repo}/pulls?state=all&per_page=100&head=${owner}:${branch}`);
136	  if (prs.code) {
137	    log(`WARN could not read pull requests for ${branch}; treating it as unmerged`);
138	    return false;
139	  }
140	  try {
141	    const parsed = JSON.parse(prs.stdout || "[]") as {
142	      merged_at?: string | null;
143	      head?: { sha?: string };
144	    }[];
145	    return parsed.some((pr) => Boolean(pr.merged_at) && pr.head?.sha === tip);
146	  } catch {
147	    log(`WARN pull request list for ${branch} was not valid JSON`);
148	    return false;
149	  }
150	}
151	
152	/**
153	 * The name of the branch a run should continue, or `""` to stay on the base.
154	 *
155	 * The rule is `ordinalToResume`; this turns its answer back into the name the
156	 * caller checks out. `""` rather than `undefined` because the one caller writes it
157	 * straight to `$GITHUB_OUTPUT`, where an absent value and an empty one are the same
158	 * thing and the empty one is what the step's condition reads.
159	 */
160	export function resumableBranch(branches: readonly IssueBranch[]): string {
161	  const ordinal = ordinalToResume(branches);
162	  return branches.find((branch) => branch.ordinal === ordinal)?.name ?? "";
163	}

